using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class Studio {
 ComboBox selectionMode=new ComboBox();
 void AddPixelSelections(FlowLayoutPanel tools){var label=new Label{Text="PIXEL SELECTION",Width=170,Height=20,Margin=new Padding(3,14,3,0)};selectionMode.DropDownStyle=ComboBoxStyle.DropDownList;selectionMode.Width=170;selectionMode.Items.AddRange(new object[]{"Draw","Ellipse selection","Box selection","Polygon selection","Lasso selection"});selectionMode.SelectedIndexChanged+=delegate{canvas.SetSelectionMode(selectionMode.Text);UpdateSelectionButtons();canvas.Focus();};selectionMode.SelectedItem="Draw";var clear=Theme.Button("Deselect   Ctrl+D",delegate{canvas.ClearSelection();selectionMode.SelectedItem="Draw";canvas.Focus();});clear.Width=170;AddTopSelectionButtons();Control[] controls={};int index=tools.Controls.GetChildIndex(toolButtons["Eraser"])+1;foreach(var c in controls){tools.Controls.Add(c);tools.Controls.SetChildIndex(c,index++);}canvas.SelectionFinished=delegate{canvas.Focus();};}
 bool HandleSelectionKeys(Keys key){if(ActiveControl is TextBoxBase||ActiveControl is NumericUpDown)return false;if(canvas.Doc==null||canvas.Doc.Selected.Is3D)return false;if(key==Keys.B){selectionButtons["Box selection"].PerformClick();return true;}if(canvas.Doc.Selected.IsVector){if(key==Keys.Enter&&canvas.SelectionMode=="Polygon selection"){canvas.FinishSelection();return true;}if(key==(Keys.Control|Keys.D)){canvas.CancelVector();canvas.SetSelectionMode("Draw");return true;}if((key&Keys.Modifiers)==Keys.Control)return false;var code=key&Keys.KeyCode;if(code==Keys.Add||code==Keys.Oemplus){canvas.EditCurvePoint(true);return true;}if(code==Keys.Subtract||code==Keys.OemMinus){canvas.EditCurvePoint(false);return true;}return false;}if(key==(Keys.Control|Keys.D)){canvas.ClearSelection();selectionMode.SelectedItem="Draw";return true;}if(key==Keys.Enter&&canvas.SelectionMode=="Polygon selection"){canvas.FinishSelection();return true;}if(key==Keys.Escape&&canvas.SelectionMode!="Draw"){canvas.CancelSelectionDraft();selectionMode.SelectedItem="Draw";canvas.ClearSelection();SelectTool("Select");return true;}if(key==Keys.Delete&&canvas.HasSelection){canvas.DeleteSelectedPixels();return true;}return false;}
}
partial class Canvas {
 public void TestPixelSelections(){Zoom=1;Offset=PointF.Empty;SelectGuide("Freehand");PressureMode="No pressure";Smoothing=0;Predictive=false;Tool="Pen";BrushSize=20;BrushOpacity=BrushFlow=BrushHardness=1;Ink=Color.Blue;
  foreach(string mode in new[]{"Box selection","Polygon selection","Lasso selection"}){ClearSelection();SetSelectionMode(mode);if(mode=="Box selection")TestDrag(new Point(40,40),new Point(160,160));else if(mode=="Polygon selection"){TestDrag(new Point(40,40),new Point(40,40));TestDrag(new Point(160,40),new Point(160,40));TestDrag(new Point(100,160),new Point(100,160));FinishSelection();}else{OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,40,40,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,160,40,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,160,160,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,40,160,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,40,40,0));}SetSelectionMode("Draw");if(!HasSelection||SelectionMask[80*Doc.Width+100]==0||SelectionMask[20*Doc.Width+20]!=0)throw new Exception("Selection mask "+mode);using(var g=Graphics.FromImage(Doc.Selected.Image))g.Clear(Color.Transparent);Tool="Pen";TestDrag(new Point(10,80),new Point(190,80));if(Doc.Selected.Image.GetPixel(100,80).A==0||Doc.Selected.Image.GetPixel(20,80).A!=0)throw new Exception("Selection drawing clip "+mode);using(var g=Graphics.FromImage(Doc.Selected.Image))g.Clear(Color.Red);Tool="Eraser";TestDrag(new Point(10,80),new Point(190,80));if(Doc.Selected.Image.GetPixel(100,80).A!=0||Doc.Selected.Image.GetPixel(20,80).A!=255)throw new Exception("Selection erasing clip "+mode);TestDraftPaint();}ClearSelection();SetSelectionMode("Draw");}
 Region selectionRegion;int selectionOperation;StrokeSmoother lassoSmoother;
 public string SelectionMode="Draw";public byte[] SelectionMask;public Action SelectionFinished;GraphicsPath selectionPath;List<PointF> selectionPoints=new List<PointF>();bool selectionDragging;PointF selectionAnchor,selectionPointer;
 public bool HasSelection {get{return SelectionMask!=null;}}
 public void SetSelectionMode(string mode){VectorBoxMode=false;EndStroke();CancelSelectionDraft();SelectionMode=mode;RefreshCursor();}
 public void ClearSelection(){CancelSelectionDraft();if(selectionRegion!=null){selectionRegion.Dispose();selectionRegion=null;}SelectionMask=null;if(selectionPath!=null){selectionPath.Dispose();selectionPath=null;}Invalidate();}
 public void CancelSelectionDraft(){ellipseStage=0;ellipseCircle=false;selectionDragging=false;lassoSmoother=null;selectionPoints.Clear();Capture=false;Invalidate();}
 PointF ClampSelection(PointF p){return new PointF(Math.Max(0,Math.Min(Doc.Width,p.X)),Math.Max(0,Math.Min(Doc.Height,p.Y)));}
 bool SelectionDown(PointF p){if(SelectionMode=="Ellipse selection")return EllipseSelectionDown(p);if(SelectionMode=="Draw")return false;p=ClampSelection(p);selectionPointer=p;if(selectionPoints.Count==0)selectionOperation=(ModifierKeys&Keys.Control)!=0?-1:(ModifierKeys&Keys.Shift)!=0?1:0;if(SelectionMode=="Polygon selection"){if(selectionPoints.Count>=3&&StrokeSession.Distance(p,selectionPoints[0])*Zoom<10){FinishSelection();return true;}if(selectionPoints.Count==0||StrokeSession.Distance(p,selectionPoints.Last())>.5f)selectionPoints.Add(p);Invalidate();return true;}selectionAnchor=p;selectionPoints.Clear();selectionPoints.Add(p);if(SelectionMode=="Lasso selection")lassoSmoother=new StrokeSmoother(p,50,Zoom,delegate(PointF q){if(StrokeSession.Distance(q,selectionPoints.Last())*Zoom>=.5)selectionPoints.Add(q);});selectionDragging=true;Capture=true;Invalidate();return true;}
 bool SelectionMove(PointF p){if(SelectionMode=="Ellipse selection"){selectionPointer=ClampSelection(p);Invalidate();return true;}if(Doc==null||Doc.Selected.Is3D||SelectionMode=="Draw")return false;p=ClampSelection(p);selectionPointer=p;if(selectionDragging&&SelectionMode=="Lasso selection")lassoSmoother.Move(p);Invalidate();return true;}
 bool SelectionUp(PointF p){if(SelectionMode=="Ellipse selection"){if(ellipseCircle&&selectionDragging){selectionPointer=ClampSelection(p);selectionDragging=false;FinishSelection();}return true;}if(Doc==null||Doc.Selected.Is3D||SelectionMode=="Draw")return false;if(selectionDragging){selectionPointer=ClampSelection(p);if(SelectionMode=="Lasso selection"){lassoSmoother.Move(selectionPointer);lassoSmoother.Finish();}selectionDragging=false;Capture=false;FinishSelection();}return true;}
 public void FinishSelection(){if(Doc==null||Doc.Selected.Is3D)return;var path=new GraphicsPath();if(SelectionMode=="Ellipse selection"){path.Dispose();path=EllipseSelectionPath();if(path.PointCount==0)return;}else if(SelectionMode=="Box selection"){var r=RectangleF.FromLTRB(Math.Min(selectionAnchor.X,selectionPointer.X),Math.Min(selectionAnchor.Y,selectionPointer.Y),Math.Max(selectionAnchor.X,selectionPointer.X),Math.Max(selectionAnchor.Y,selectionPointer.Y));if(r.Width<1||r.Height<1){path.Dispose();CancelSelectionDraft();return;}path.AddRectangle(r);}else{if(selectionPoints.Count<3){path.Dispose();return;}path.AddPolygon(selectionPoints.ToArray());}if(Doc.Selected.IsVector){SelectPathsInRegion(path,selectionOperation);path.Dispose();CancelSelectionDraft();if(SelectionFinished!=null)SelectionFinished();return;}if(selectionOperation==0||selectionRegion==null){if(selectionRegion!=null)selectionRegion.Dispose();selectionRegion=new Region();selectionRegion.MakeEmpty();}if(selectionOperation<0)selectionRegion.Exclude(path);else selectionRegion.Union(path);path.Dispose();BuildSelectionMask();BuildSelectionOutline();ellipseStage=0;ellipseCircle=false;selectionDragging=false;selectionPoints.Clear();lassoSmoother=null;Capture=false;if(SelectionFinished!=null)SelectionFinished();RefreshCursor();}
 void BuildSelectionMask(){SelectionMask=new byte[Doc.Width*Doc.Height];using(var region=selectionRegion.Clone())using(var matrix=new Matrix()){foreach(var r in region.GetRegionScans(matrix)){int x0=Math.Max(0,(int)Math.Ceiling(r.Left-.5f)),x1=Math.Min(Doc.Width,(int)Math.Ceiling(r.Right-.5f)),y0=Math.Max(0,(int)Math.Ceiling(r.Top-.5f)),y1=Math.Min(Doc.Height,(int)Math.Ceiling(r.Bottom-.5f));for(int y=y0;y<y1;y++)for(int x=x0;x<x1;x++)SelectionMask[y*Doc.Width+x]=1;}}}
 public unsafe void DeleteSelectedPixels(){if(!HasSelection||Doc==null||!Doc.Selected.IsRaster||Doc.Selected.IsLocked||!Doc.Selected.Visible)return;EndStroke();if(BeforeStroke!=null)BeforeStroke();var image=Doc.Selected.Image;var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{for(int y=0;y<image.Height;y++){byte* row=(byte*)data.Scan0+y*data.Stride;for(int x=0;x<image.Width;x++)if(SelectionMask[y*image.Width+x]!=0)row[x*4+3]=0;}}finally{image.UnlockBits(data);}if(AfterStroke!=null)AfterStroke();Invalidate();}
 void PaintSelection(Graphics g){if(TransformMode!=null)return;if(Doc.Selected.Is3D)return;var state=g.Save();g.TranslateTransform(Offset.X,Offset.Y);g.ScaleTransform(Zoom,Zoom);g.SetClip(new Rectangle(0,0,Doc.Width,Doc.Height));using(var white=new Pen(Color.White,2/Zoom))using(var black=new Pen(Color.Black,1/Zoom)){black.DashStyle=DashStyle.Dash;if(Doc.Selected.IsRaster&&selectionPath!=null){g.DrawPath(white,selectionPath);g.DrawPath(black,selectionPath);}if(selectionPoints.Count>0){using(var draftPath=SelectionMode=="Ellipse selection"?EllipseSelectionPath():new GraphicsPath()){if(SelectionMode=="Ellipse selection"){}else if(SelectionMode=="Box selection"){var r=RectangleF.FromLTRB(Math.Min(selectionAnchor.X,selectionPointer.X),Math.Min(selectionAnchor.Y,selectionPointer.Y),Math.Max(selectionAnchor.X,selectionPointer.X),Math.Max(selectionAnchor.Y,selectionPointer.Y));if(r.Width>0&&r.Height>0)draftPath.AddRectangle(r);}else{var pts=new List<PointF>(selectionPoints);pts.Add(selectionPointer);if(pts.Count>1)draftPath.AddLines(pts.ToArray());}if(draftPath.PointCount>0){g.DrawPath(white,draftPath);g.DrawPath(black,draftPath);}}}}g.Restore(state);}
}
}
